<template><main class="auth"><CwaLogo/><h1>CwaAX</h1><p>تسجيل الدخول</p><input v-model="email" type="email" placeholder="البريد الإلكتروني"><input v-model="password" type="password" placeholder="كلمة المرور"><div v-if="error" class="error">{{error}}</div><button class="primary" @click="login">تسجيل الدخول</button><button class="link" @click="router.push('/register')">إنشاء حساب جديد</button></main></template>
<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {signInWithEmailAndPassword} from 'firebase/auth';import {auth} from '../firebase';import CwaLogo from '../components/CwaLogo.vue';const router=useRouter(),email=ref(''),password=ref(''),error=ref('');const login=async()=>{error.value='';try{await signInWithEmailAndPassword(auth,email.value,password.value);router.replace('/home')}catch(e){error.value='تعذر تسجيل الدخول. تحقق من البيانات.'}}</script><style scoped>.auth{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:30px}.auth h1{margin:15px 0 0;font-size:34px}.auth p{color:var(--muted)}.auth input{width:min(390px,100%);height:54px;margin:7px 0;border:1px solid var(--line);border-radius:14px;padding:0 16px;outline:none}.primary{width:min(390px,100%);height:54px;margin-top:12px;border:0;border-radius:14px;background:var(--green);color:#fff;font-weight:700}.link{margin-top:14px;border:0;background:none;color:var(--green)}.error{color:#c54d59;margin:8px}
</style>
